"use client";

import type { Job } from "@/lib/mock-data";
import { Button } from "@/components/ui/button";

interface JobEditFormProps {
  job: Job;
  onCancel: () => void;
}

function FormField({
  label,
  children,
}: {
  label: string;
  children: React.ReactNode;
}) {
  return (
    <div className="space-y-1.5">
      <label className="block text-xs font-medium text-text-secondary">
        {label}
      </label>
      {children}
    </div>
  );
}

function TextInput({
  defaultValue,
  placeholder,
}: {
  defaultValue?: string;
  placeholder?: string;
}) {
  return (
    <input
      type="text"
      readOnly
      defaultValue={defaultValue}
      placeholder={placeholder}
      className="w-full rounded-lg border border-border bg-surface-elevated/60 px-3 py-2 text-sm font-mono text-text-primary placeholder:text-text-secondary/40 outline-none focus:border-primary/40 focus:ring-1 focus:ring-primary/20 transition-colors"
    />
  );
}

function TextArea({
  defaultValue,
  placeholder,
  rows = 3,
}: {
  defaultValue?: string;
  placeholder?: string;
  rows?: number;
}) {
  return (
    <textarea
      readOnly
      defaultValue={defaultValue}
      placeholder={placeholder}
      rows={rows}
      className="w-full rounded-lg border border-border bg-surface-elevated/60 px-3 py-2 text-sm font-mono text-text-primary placeholder:text-text-secondary/40 outline-none focus:border-primary/40 focus:ring-1 focus:ring-primary/20 transition-colors resize-none"
    />
  );
}

function SelectInput({
  defaultValue,
  options,
}: {
  defaultValue: string;
  options: string[];
}) {
  return (
    <select
      defaultValue={defaultValue}
      className="w-full rounded-lg border border-border bg-surface-elevated/60 px-3 py-2 text-sm font-mono text-text-primary outline-none focus:border-primary/40 focus:ring-1 focus:ring-primary/20 transition-colors cursor-pointer appearance-none"
    >
      {options.map((opt) => (
        <option key={opt} value={opt}>
          {opt}
        </option>
      ))}
    </select>
  );
}

function ToggleSwitch({ defaultChecked }: { defaultChecked: boolean }) {
  return (
    <button
      type="button"
      className={`relative inline-flex h-5 w-9 flex-shrink-0 cursor-pointer rounded-full border-2 border-transparent transition-colors duration-200 ${
        defaultChecked ? "bg-primary" : "bg-border"
      }`}
    >
      <span
        className={`pointer-events-none inline-block h-4 w-4 transform rounded-full bg-text-primary shadow transition duration-200 ${
          defaultChecked ? "translate-x-4" : "translate-x-0"
        }`}
      />
    </button>
  );
}

export function JobEditForm({ job, onCancel }: JobEditFormProps) {
  const envVarStr =
    Object.keys(job.envVars).length > 0
      ? Object.entries(job.envVars)
          .map(([k, v]) => `${k}=${v}`)
          .join("\n")
      : "";

  return (
    <div className="flex-1 overflow-y-auto p-6">
      <h2 className="text-lg font-semibold text-text-primary mb-6">
        Edit Configuration
      </h2>

      <div className="max-w-2xl space-y-5">
        <FormField label="Name">
          <TextInput defaultValue={job.name} />
        </FormField>

        <FormField label="Command">
          <TextArea defaultValue={job.command} rows={2} />
        </FormField>

        <div className="grid grid-cols-2 gap-4">
          <FormField label="Schedule">
            <TextInput defaultValue={job.schedule} placeholder="*/5 * * * *" />
          </FormField>
          <FormField label="Schedule Mode">
            <SelectInput
              defaultValue={job.scheduleMode}
              options={["cron", "interval", "once"]}
            />
          </FormField>
        </div>

        <FormField label="Timezone">
          <TextInput defaultValue="UTC" />
        </FormField>

        <FormField label="Working Directory">
          <TextInput defaultValue={job.workingDir} />
        </FormField>

        <div className="grid grid-cols-2 gap-4">
          <FormField label="Shell">
            <TextInput defaultValue={job.shell} />
          </FormField>
          <FormField label="Timeout">
            <TextInput defaultValue={job.timeout} />
          </FormField>
        </div>

        <div className="grid grid-cols-2 gap-4">
          <FormField label="Allow Concurrent">
            <div className="pt-1">
              <ToggleSwitch defaultChecked={job.allowConcurrent} />
            </div>
          </FormField>
          <FormField label="Max Retries">
            <TextInput defaultValue={String(job.maxRetries)} />
          </FormField>
        </div>

        <FormField label="Pre-run Hook">
          <TextArea
            defaultValue={job.preHook}
            placeholder="Script to run before the job..."
            rows={2}
          />
        </FormField>

        <FormField label="Post-run Hook">
          <TextArea
            defaultValue={job.postHook}
            placeholder="Script to run after the job..."
            rows={2}
          />
        </FormField>

        <FormField label="Environment Variables">
          <TextArea
            defaultValue={envVarStr}
            placeholder="KEY=VALUE (one per line)"
            rows={3}
          />
        </FormField>

        {/* Actions */}
        <div className="flex items-center gap-3 pt-4 border-t border-border">
          <Button variant="primary">Save Changes</Button>
          <Button variant="secondary" onClick={onCancel}>
            Cancel
          </Button>
        </div>
      </div>
    </div>
  );
}
