"use client";

import { Card, CardHeader, CardTitle } from "@/components/ui/card";
import { Button } from "@/components/ui/button";
import { PencilSquareIcon } from "@heroicons/react/20/solid";
import type { Job } from "@/lib/mock-data";

interface JobConfigViewProps {
  job: Job;
  onEdit: () => void;
}

function ConfigRow({ label, value }: { label: string; value: string }) {
  return (
    <div className="flex items-start py-2.5 border-b border-border/30 last:border-0">
      <dt className="w-40 flex-shrink-0 text-xs font-medium text-text-secondary">
        {label}
      </dt>
      <dd className="text-sm font-mono text-text-primary break-all whitespace-pre-wrap">
        {value}
      </dd>
    </div>
  );
}

export function JobConfigView({ job, onEdit }: JobConfigViewProps) {
  const envVarStr =
    Object.keys(job.envVars).length > 0
      ? Object.entries(job.envVars)
          .map(([k, v]) => `${k}=${v}`)
          .join("\n")
      : "None";

  return (
    <div className="flex-1 overflow-y-auto p-6 space-y-6">
      <div className="flex items-center justify-between">
        <h2 className="text-lg font-semibold text-text-primary">
          Configuration
        </h2>
        <Button variant="secondary" size="sm" onClick={onEdit}>
          <PencilSquareIcon className="h-3.5 w-3.5" />
          Edit
        </Button>
      </div>

      <Card>
        <dl>
          <ConfigRow label="Schedule" value={job.schedule || "None"} />
          <ConfigRow label="Schedule Mode" value={job.scheduleMode} />
          <ConfigRow label="Command" value={job.command} />
          <ConfigRow label="Working Dir" value={job.workingDir || "None"} />
          <ConfigRow label="Shell" value={job.shell} />
          <ConfigRow label="Timeout" value={job.timeout} />
          <ConfigRow label="Max Retries" value={String(job.maxRetries)} />
          <ConfigRow
            label="Allow Concurrent"
            value={job.allowConcurrent ? "Yes" : "No"}
          />
          <ConfigRow label="Pre-hook" value={job.preHook || "None"} />
          <ConfigRow label="Post-hook" value={job.postHook || "None"} />
          <ConfigRow label="Env Vars" value={envVarStr} />
          <ConfigRow label="Created" value={job.created} />
          <ConfigRow label="Last Run" value={job.lastRun} />
        </dl>
      </Card>
    </div>
  );
}
