"use client";

import { cn } from "@/lib/utils";
import { relativeTime, type Job, type JobStatus, type Run } from "@/lib/mock-data";
import { Button } from "@/components/ui/button";
import {
  PlusIcon,
  ArrowLeftIcon,
  HomeIcon,
  PencilSquareIcon,
  PlayIcon,
  TrashIcon,
} from "@heroicons/react/20/solid";

/* ── Status dot color mapping ────────────────────────────────────────────── */
const statusDot: Record<JobStatus, string> = {
  ok: "bg-success",
  failed: "bg-error",
  running: "bg-info",
  disabled: "bg-text-secondary/30",
};

/* ── Types ───────────────────────────────────────────────────────────────── */
export type JobSubPage = "home" | "config" | "editor" | "log";

interface SidebarProps {
  jobs: Job[];
  runs: Run[];
  selectedJobId: string | null;
  onSelectJob: (id: string) => void;
  onDeselectJob: () => void;
  onSelectRun: (runId: string) => void;
  onSetSubPage: (page: JobSubPage) => void;
  onDeleteClick: () => void;
  onTriggerOverride: () => void;
  selectedRunId: string | null;
  activeSubPage: JobSubPage;
}

/* ── Icon Button with tooltip ────────────────────────────────────────────── */
function IconAction({
  icon,
  label,
  onClick,
  active,
  destructive,
}: {
  icon: React.ReactNode;
  label: string;
  onClick?: () => void;
  active?: boolean;
  destructive?: boolean;
}) {
  return (
    <div className="relative group">
      <button
        onClick={onClick}
        className={cn(
          "flex items-center justify-center h-9 w-9 rounded-lg transition-colors cursor-pointer",
          destructive
            ? "text-error/60 hover:text-error hover:bg-error/10"
            : active
              ? "text-primary bg-primary/10"
              : "text-text-secondary hover:text-text-primary hover:bg-surface-elevated"
        )}
        aria-label={label}
      >
        {icon}
      </button>
      {/* Tooltip */}
      <div className="absolute left-full top-1/2 -translate-y-1/2 ml-2 px-2 py-1 rounded bg-surface-elevated border border-border text-[11px] text-text-primary font-medium whitespace-nowrap opacity-0 pointer-events-none group-hover:opacity-100 transition-opacity z-50 shadow-lg">
        {label}
      </div>
    </div>
  );
}

/* ── List View Sidebar (State 1) ─────────────────────────────────────────── */
function ListViewSidebar({
  jobs,
  onSelectJob,
}: {
  jobs: Job[];
  onSelectJob: (id: string) => void;
}) {
  return (
    <>
      {/* Header */}
      <div className="flex items-center justify-between px-4 py-3 border-b border-border">
        <h2 className="text-xs font-semibold uppercase tracking-wider text-text-secondary">
          Jobs
        </h2>
        <Button variant="primary" size="sm" className="h-7 text-xs gap-1">
          <PlusIcon className="h-3.5 w-3.5" />
          Create
        </Button>
      </div>

      {/* Section label */}
      <div className="px-4 pt-3 pb-1.5">
        <p className="text-[10px] font-semibold uppercase tracking-wider text-text-secondary/50">
          Recent Jobs
        </p>
      </div>

      {/* Job list */}
      <nav className="flex-1 overflow-y-auto pb-2">
        {jobs.map((job) => (
          <button
            key={job.id}
            onClick={() => onSelectJob(job.id)}
            className="w-full flex items-start gap-3 px-4 py-3 text-left transition-colors cursor-pointer hover:bg-surface-elevated/50"
          >
            <span
              className={cn(
                "mt-1.5 h-2.5 w-2.5 rounded-full flex-shrink-0",
                statusDot[job.status],
                job.status === "running" && "animate-pulse"
              )}
            />
            <div className="min-w-0 flex-1">
              <p className="text-sm font-medium text-text-primary truncate">
                {job.name}
              </p>
              <p className="text-[11px] text-text-secondary/60 mt-0.5">
                {job.nextRun ? `Next: ${job.nextRun}` : "Not scheduled"}
              </p>
              <p className="text-[10px] mt-0.5">
                {job.enabled ? (
                  <span className="text-success/70">Enabled</span>
                ) : (
                  <span className="text-text-secondary/40">Disabled</span>
                )}
              </p>
            </div>
          </button>
        ))}
      </nav>
    </>
  );
}

/* ── Detail View Sidebar (State 2) ───────────────────────────────────────── */
function DetailViewSidebar({
  job,
  runs,
  onBack,
  onSelectRun,
  onSetSubPage,
  onDeleteClick,
  onTriggerOverride,
  selectedRunId,
  activeSubPage,
}: {
  job: Job;
  runs: Run[];
  onBack: () => void;
  onSelectRun: (runId: string) => void;
  onSetSubPage: (page: JobSubPage) => void;
  onDeleteClick: () => void;
  onTriggerOverride: () => void;
  selectedRunId: string | null;
  activeSubPage: JobSubPage;
}) {
  const jobRuns = runs.filter((r) => r.jobId === job.id).slice(0, 10);

  return (
    <>
      {/* Header */}
      <div className="px-4 py-3 border-b border-border">
        <h2 className="text-xs font-semibold uppercase tracking-wider text-text-secondary">
          Jobs
        </h2>
      </div>

      {/* Back button */}
      <button
        onClick={onBack}
        className="flex items-center gap-2 w-full px-4 py-2.5 text-sm text-text-secondary hover:text-text-primary transition-colors cursor-pointer border-b border-border"
      >
        <ArrowLeftIcon className="h-3.5 w-3.5" />
        <span className="font-medium">Back to all jobs</span>
      </button>

      {/* Compact icon action bar */}
      <div className="px-4 py-3 border-b border-border">
        <p className="text-[10px] font-semibold uppercase tracking-wider text-text-secondary/50 mb-2">
          Actions
        </p>
        <div className="flex items-center gap-1">
          <IconAction
            icon={<HomeIcon className="h-4 w-4" />}
            label="Job Home"
            onClick={() => onSetSubPage("home")}
            active={activeSubPage === "home"}
          />
          <IconAction
            icon={<PlayIcon className="h-4 w-4" />}
            label="Trigger"
          />
          <IconAction
            icon={<PencilSquareIcon className="h-4 w-4" />}
            label="Edit Configuration"
            onClick={() => onSetSubPage("config")}
            active={activeSubPage === "config"}
          />
          <IconAction
            icon={<TrashIcon className="h-4 w-4" />}
            label="Delete"
            onClick={onDeleteClick}
            destructive
          />
        </div>
        {/* Trigger with Override link */}
        <button
          onClick={onTriggerOverride}
          className="mt-2 text-[11px] text-text-secondary hover:text-primary transition-colors cursor-pointer font-medium"
        >
          Trigger with Override...
        </button>
      </div>

      {/* Recent Runs */}
      <div className="flex-1 overflow-y-auto">
        <div className="px-4 pt-3 pb-1.5">
          <p className="text-[10px] font-semibold uppercase tracking-wider text-text-secondary/50">
            Recent Runs
          </p>
        </div>
        <div className="pb-2">
          {jobRuns.length === 0 ? (
            <p className="px-4 py-2 text-xs text-text-secondary/50">
              No runs yet.
            </p>
          ) : (
            jobRuns.map((run) => (
              <button
                key={run.id}
                onClick={() => onSelectRun(run.id)}
                className={cn(
                  "w-full flex items-center gap-2.5 px-4 py-2 text-left transition-colors cursor-pointer",
                  selectedRunId === run.id
                    ? "bg-surface-elevated"
                    : "hover:bg-surface-elevated/50"
                )}
              >
                <span
                  className={cn(
                    "h-2 w-2 rounded-full flex-shrink-0",
                    run.status === "success" && "bg-success",
                    run.status === "failed" && "bg-error",
                    run.status === "running" && "bg-info animate-pulse",
                    run.status === "killed" && "bg-warning"
                  )}
                />
                <div className="min-w-0 flex-1">
                  <span className="text-xs font-mono text-text-primary truncate block">
                    Run {run.id.length > 12 ? run.id.slice(0, 8) : run.id.replace("r-", "")}
                  </span>
                </div>
                <span className="text-[10px] font-mono text-text-secondary/50 flex-shrink-0">
                  {relativeTime(run.started)}
                </span>
              </button>
            ))
          )}
        </div>
      </div>
    </>
  );
}

/* ── Exported Sidebar ────────────────────────────────────────────────────── */
export function Sidebar({
  jobs,
  runs,
  selectedJobId,
  onSelectJob,
  onDeselectJob,
  onSelectRun,
  onSetSubPage,
  onDeleteClick,
  onTriggerOverride,
  selectedRunId,
  activeSubPage,
}: SidebarProps) {
  const selectedJob = selectedJobId
    ? jobs.find((j) => j.id === selectedJobId)
    : null;

  return (
    <aside className="flex w-64 flex-col border-r border-border bg-surface overflow-hidden flex-shrink-0">
      {selectedJob ? (
        <DetailViewSidebar
          job={selectedJob}
          runs={runs}
          onBack={onDeselectJob}
          onSelectRun={onSelectRun}
          onSetSubPage={onSetSubPage}
          onDeleteClick={onDeleteClick}
          onTriggerOverride={onTriggerOverride}
          selectedRunId={selectedRunId}
          activeSubPage={activeSubPage}
        />
      ) : (
        <ListViewSidebar jobs={jobs} onSelectJob={onSelectJob} />
      )}
    </aside>
  );
}
